const templateMap = {
    peachy_dawn: "template1",
    blue_sky: "template2",
    vivid_colors: "template4"
};

/** ──────────────────────────────────────────────────────────
 *  Component
 *  ────────────────────────────────────────────────────────── */
export default function Template({
    templateSetting = {
        template: "none",
        cardSize: "102x152",
        sided: "qa_same_side",
        orientation: "horizontal"
    },
    setTemplateSetting = () => {}
}) {
    const handleTemplateClick = key => {
        if (templateSetting.template === key) {
            setTemplateSetting({ ...templateSetting, template: "none" });
        } else {
            setTemplateSetting({ ...templateSetting, template: key });
        }
    };

    const handleSizeChange = size => {
        setTemplateSetting({ ...templateSetting, cardSize: size });
    };

    const handleSidedChange = sided => {
        setTemplateSetting({ ...templateSetting, sided });
    };

    const handleOrientationChange = orientation => {
        setTemplateSetting({ ...templateSetting, orientation });
    };

    return (
        <div style={styles.container}>
            {/* Card Size */}
            <label style={styles.label}>Card Size</label>

            <select
                style={styles.select}
                value={templateSetting.cardSize}
                onChange={e => setTemplateSetting({ ...templateSetting, cardSize: e.target.value })}
            >
                {CARD_SIZES.map(({ key, label }) => (
                    <option key={key} value={key}>
                        {label}
                    </option>
                ))}
            </select>

            {/* One/Two Sided */}
            <label style={styles.label}>One-sided or Two-sided</label>
            <div style={styles.grid}>
                {SIDE_OPTIONS.map(({ key, icon }) => {
                    const selected = templateSetting.sided === key;
                    return (
                        <button
                            key={key}
                            style={{ ...styles.card, ...(selected ? styles.cardSelected : {}) }}
                            onClick={() => handleSidedChange(key)}
                        >
                            <div
                                style={{
                                    ...styles.cardImgWrapper,
                                    color: selected ? "white" : "#666",
                                    display: "flex",
                                    justifyContent: "center",
                                    alignItems: "center"
                                }}
                            >
                                {icon}
                            </div>
                        </button>
                    );
                })}
            </div>

            {/* Horizontal/Vertical */}
            <label style={styles.label}>Horizontal or Vertical</label>
            <div style={styles.grid}>
                {ORIENTATION_OPTIONS.map(({ key, icon }) => {
                    const selected = templateSetting.orientation === key;
                    return (
                        <button
                            key={key}
                            style={{ ...styles.card, ...(selected ? styles.cardSelected : {}) }}
                            onClick={() => handleOrientationChange(key)}
                        >
                            <div
                                style={{
                                    ...styles.cardImgWrapper,
                                    color: selected ? "white" : "#666",
                                    display: "flex",
                                    justifyContent: "center",
                                    alignItems: "center"
                                }}
                            >
                                {icon}
                            </div>
                        </button>
                    );
                })}
            </div>

            {/* Template Selection */}
            <label style={styles.label}>Template</label>
            <div style={styles.grid}>
                {TYPE_OPTIONS.map(({ key, img, label }) => {
                    const selected = templateSetting.template === key;
                    return (
                        <button
                            key={key}
                            style={{ ...styles.card, ...(selected ? styles.cardSelected : {}) }}
                            onClick={() => handleTemplateClick(key)}
                        >
                            <div style={styles.cardImgWrapper}>
                                <img
                                    src={img}
                                    alt={label}
                                    style={{
                                        width: "100%",
                                        height: "100%",
                                        objectFit: "contain",
                                        borderRadius: "8px"
                                    }}
                                />
                            </div>
                        </button>
                    );
                })}
            </div>
        </div>
    );
}
